syntax:
For an associative container 'container' with element type 'T':

// Search for an element equal to 'value'
iterator find(const T& value);

// Count elements equal to 'value'
size_type count(const T& value) const;

// Find the first position where 'value' can be inserted without breaking order
iterator lower_bound(const T& value);

// Find the position after the last occurrence of 'value'
iterator upper_bound(const T& value);

// Get the range of elements equal to 'value'
pair<iterator, iterator> equal_range(const T& value);

// Retrieve the container's comparison object
key_compare key_comp() const;
value_compare value_comp() const;

code_example:
#include <iostream>
#include <set>
int main() {
    std::set<int> s = {1, 3, 5, 7, 9};
    int value = 5;
    auto it = s.find(value);
    if (it != s.end()) {
        std::cout << "Found " << *it << " at position." << std::endl;
    }
    auto range = s.equal_range(value);
    std::cout << "Elements equal to " << value << ":" << std::endl;
    for (auto iter = range.first; iter != range.second; ++iter) {
        std::cout << *iter << " ";
    }
    std::cout << std::endl;
    return 0;
}
